"use client"

import * as React from "react"
import { type Table } from "@tanstack/react-table"
import { RiSettings3Line } from "@remixicon/react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

function DataTableColumnToggle<TData>({
  table,
  columnLabels = {},
}: {
  table: Table<TData>
  /** Override display labels for specific column IDs e.g. `{ dueDate: "Due date" }` */
  columnLabels?: Record<string, string>
}) {
  const hidable = table.getAllColumns().filter(col => col.getCanHide())

  function getLabel(id: string) {
    if (columnLabels[id]) return columnLabels[id]
    return id.charAt(0).toUpperCase() + id.slice(1).replace(/([A-Z])/g, " $1")
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" size="sm" className="rounded-md" />}>
        <RiSettings3Line />
        Columns
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuGroup>
          {hidable.map(col => (
            <DropdownMenuCheckboxItem
              key={col.id}
              checked={col.getIsVisible()}
              onClick={() => col.toggleVisibility(!col.getIsVisible())}
            >
              {getLabel(col.id)}
            </DropdownMenuCheckboxItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export { DataTableColumnToggle }

"use client"

import * as React from "react"
import { RiCloseLine, RiFilterLine, RiSearchLine } from "@remixicon/react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover"

type Option = { value: string; label: string }

function DataTableFacetedFilter({
  title,
  options,
  selectedValues,
  onSelectionChange,
  icon,
}: {
  title: string
  /** Pass `string[]` for simple lists, or `{ value, label }[]` for distinct display labels. */
  options: string[] | Option[]
  selectedValues: string[]
  onSelectionChange: (values: string[]) => void
  icon?: React.ReactNode
}) {
  const [search, setSearch] = React.useState("")

  const normalised: Option[] = (options as any[]).map(o =>
    typeof o === "string" ? { value: o, label: o } : o
  )

  const filtered = normalised.filter(o =>
    o.label.toLowerCase().includes(search.toLowerCase())
  )

  const count = selectedValues.length

  function toggle(value: string) {
    const next = selectedValues.includes(value)
      ? selectedValues.filter(v => v !== value)
      : [...selectedValues, value]
    onSelectionChange(next)
  }

  return (
    <Popover>
      <PopoverTrigger render={
        <Button
          variant="outline"
          size="sm"
          className={cn("rounded-md", count > 0 && "border-primary/40 bg-primary/5 text-foreground")}
        >
          {icon ?? <RiFilterLine className="opacity-60" />}
          {title}
          {count > 0 && (
            <span className="ml-0.5 flex size-4 items-center justify-center rounded-full bg-primary text-[10px] font-semibold text-primary-foreground">
              {count}
            </span>
          )}
          {count > 0 && (
            <span
              role="button"
              aria-label="Clear filter"
              onClick={e => { e.stopPropagation(); onSelectionChange([]) }}
              className="ml-0.5 flex size-4 items-center justify-center rounded-full hover:bg-primary/20 transition-colors"
            >
              <RiCloseLine className="size-3" />
            </span>
          )}
        </Button>
      } />
      <PopoverContent className="w-52 gap-0 p-0" align="start" sideOffset={6}>
        <div className="relative border-b">
          <RiSearchLine className="absolute left-3 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground pointer-events-none" />
          <input
            autoFocus
            placeholder={title}
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full bg-transparent py-2.5 pl-9 pr-3 text-sm outline-none placeholder:text-muted-foreground"
          />
        </div>
        <div className="max-h-60 overflow-y-auto p-1">
          {filtered.length ? filtered.map(option => (
            <button
              key={option.value}
              onClick={() => toggle(option.value)}
              className="flex w-full items-center gap-2.5 rounded-md px-2 py-1.5 text-sm hover:bg-accent text-left"
            >
              <Checkbox
                checked={selectedValues.includes(option.value)}
                tabIndex={-1}
                className="pointer-events-none"
              />
              {option.label}
            </button>
          )) : (
            <p className="py-6 text-center text-xs text-muted-foreground">No results.</p>
          )}
        </div>
        {count > 0 && (
          <div className="border-t p-1">
            <button
              onClick={() => onSelectionChange([])}
              className="w-full rounded-md px-2 py-1.5 text-center text-xs text-muted-foreground hover:bg-accent hover:text-foreground"
            >
              Clear filter
            </button>
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}

export { DataTableFacetedFilter }

"use client"

import * as React from "react"
import { type Table } from "@tanstack/react-table"
import {
  RiArrowLeftDoubleLine,
  RiArrowLeftLine,
  RiArrowRightDoubleLine,
  RiArrowRightLine,
} from "@remixicon/react"

import { Button } from "@/components/ui/button"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
} from "@/components/ui/select"

export type PaginationStyle = "minimal" | "numbered" | "full" | "simple" | "classic"

const PAGE_SIZE_OPTIONS = [5, 10, 20, 50]

function getPageNumbers(current: number, total: number): (number | "…")[] {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1)
  if (current <= 4) return [1, 2, 3, 4, 5, "…", total]
  if (current >= total - 3) return [1, "…", total - 4, total - 3, total - 2, total - 1, total]
  return [1, "…", current - 1, current, current + 1, "…", total]
}

function DataTablePagination<TData>({
  table,
  style = "minimal",
  selectedCount = 0,
  rowLabel = "row",
}: {
  table: Table<TData>
  style?: PaginationStyle
  /** Pass selected row count for the info label */
  selectedCount?: number
  /** Singular label for rows e.g. "task", "lead", "student" */
  rowLabel?: string
}) {
  const pageIndex  = table.getState().pagination.pageIndex
  const pageSize   = table.getState().pagination.pageSize
  const totalRows  = table.getFilteredRowModel().rows.length
  const from       = pageIndex * pageSize + 1
  const to         = Math.min((pageIndex + 1) * pageSize, totalRows)
  const pageCount  = table.getPageCount()
  const canPrev    = table.getCanPreviousPage()
  const canNext    = table.getCanNextPage()

  if (totalRows === 0) return null

  const infoLabel = selectedCount > 0
    ? `${selectedCount} of ${totalRows} selected`
    : `${totalRows} ${rowLabel}${totalRows !== 1 ? "s" : ""}`

  if (style === "minimal") {
    return (
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span className="text-xs">{infoLabel}</span>
        <div className="flex items-center gap-1">
          <span className="mr-2 text-xs">Page {pageIndex + 1} of {pageCount}</span>
          <Button variant="outline" size="icon-sm" onClick={() => table.previousPage()} disabled={!canPrev}>
            <RiArrowLeftLine />
          </Button>
          <Button variant="outline" size="icon-sm" onClick={() => table.nextPage()} disabled={!canNext}>
            <RiArrowRightLine />
          </Button>
        </div>
      </div>
    )
  }

  if (style === "numbered") {
    return (
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span className="text-xs">{infoLabel}</span>
        <div className="flex items-center gap-1">
          <Button variant="outline" size="icon-sm" onClick={() => table.previousPage()} disabled={!canPrev}>
            <RiArrowLeftLine />
          </Button>
          {getPageNumbers(pageIndex + 1, pageCount).map((p, i) =>
            p === "…" ? (
              <span key={`ellipsis-${i}`} className="px-1 text-muted-foreground">…</span>
            ) : (
              <Button
                key={p}
                variant={p === pageIndex + 1 ? "default" : "outline"}
                size="icon-sm"
                onClick={() => table.setPageIndex((p as number) - 1)}
              >
                {p}
              </Button>
            )
          )}
          <Button variant="outline" size="icon-sm" onClick={() => table.nextPage()} disabled={!canNext}>
            <RiArrowRightLine />
          </Button>
        </div>
      </div>
    )
  }

  if (style === "full") {
    return (
      <div className="flex flex-wrap items-center justify-between gap-3 text-sm text-muted-foreground">
        <div className="flex items-center gap-2">
          <span className="text-xs">Rows per page</span>
          <Select value={String(pageSize)} onValueChange={v => table.setPageSize(Number(v))}>
            <SelectTrigger className="h-8 w-16 text-xs">{pageSize}</SelectTrigger>
            <SelectContent>
              <SelectGroup>
                {PAGE_SIZE_OPTIONS.map(n => <SelectItem key={n} value={String(n)}>{n}</SelectItem>)}
              </SelectGroup>
            </SelectContent>
          </Select>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs">{from}–{to} of {totalRows}</span>
          <div className="flex items-center gap-1">
            <Button variant="outline" size="icon-sm" onClick={() => table.setPageIndex(0)} disabled={!canPrev}>
              <RiArrowLeftDoubleLine />
            </Button>
            <Button variant="outline" size="icon-sm" onClick={() => table.previousPage()} disabled={!canPrev}>
              <RiArrowLeftLine />
            </Button>
            <Button variant="outline" size="icon-sm" onClick={() => table.nextPage()} disabled={!canNext}>
              <RiArrowRightLine />
            </Button>
            <Button variant="outline" size="icon-sm" onClick={() => table.setPageIndex(pageCount - 1)} disabled={!canNext}>
              <RiArrowRightDoubleLine />
            </Button>
          </div>
        </div>
      </div>
    )
  }

  if (style === "simple") {
    return (
      <div className="flex items-center justify-between text-sm">
        <span className="text-muted-foreground">
          Showing{" "}
          <span className="font-medium text-foreground">{from}–{to}</span>
          {" "}of{" "}
          <span className="font-medium text-foreground">{totalRows}</span> results
        </span>
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={() => table.previousPage()} disabled={!canPrev}>
            <RiArrowLeftLine /> Previous
          </Button>
          <Button variant="ghost" size="sm" onClick={() => table.nextPage()} disabled={!canNext}>
            Next <RiArrowRightLine />
          </Button>
        </div>
      </div>
    )
  }

  // classic
  return (
    <div className="grid grid-cols-3 items-center text-sm text-muted-foreground">
      <span className="text-xs">{from}–{to} of {totalRows}</span>
      <div className="flex items-center justify-center gap-1">
        <Button variant="outline" size="icon-sm" className="rounded-full" onClick={() => table.previousPage()} disabled={!canPrev}>
          <RiArrowLeftLine />
        </Button>
        {getPageNumbers(pageIndex + 1, pageCount).map((p, i) =>
          p === "…" ? (
            <span key={`ellipsis-${i}`} className="w-8 text-center text-xs">···</span>
          ) : (
            <Button
              key={p}
              variant={p === pageIndex + 1 ? "secondary" : "outline"}
              size="icon-sm"
              className="rounded-full"
              onClick={() => table.setPageIndex((p as number) - 1)}
            >
              {p}
            </Button>
          )
        )}
        <Button variant="outline" size="icon-sm" className="rounded-full" onClick={() => table.nextPage()} disabled={!canNext}>
          <RiArrowRightLine />
        </Button>
      </div>
      <div className="flex items-center justify-end gap-2">
        <span className="text-xs">Rows</span>
        <Select value={String(pageSize)} onValueChange={v => table.setPageSize(Number(v))}>
          <SelectTrigger className="h-8 w-16 text-xs">{pageSize}</SelectTrigger>
          <SelectContent align="end">
            <SelectGroup>
              {PAGE_SIZE_OPTIONS.map(n => <SelectItem key={n} value={String(n)}>{n}</SelectItem>)}
            </SelectGroup>
          </SelectContent>
        </Select>
      </div>
    </div>
  )
}

export { DataTablePagination }

"use client"

import * as React from "react"
import { type Table } from "@tanstack/react-table"
import { RiSearchLine } from "@remixicon/react"

import { cn } from "@/lib/utils"

function DataTableSearch<TData>({
  table,
  placeholder = "Search...",
  className,
}: {
  table: Table<TData>
  placeholder?: string
  className?: string
}) {
  return (
    <div className={cn("relative flex-1 min-w-[140px] max-w-[220px]", className)}>
      <RiSearchLine className="absolute left-3 top-1/2 -translate-y-1/2 size-3.5 text-muted-foreground pointer-events-none" />
      <input
        placeholder={placeholder}
        value={(table.getState().globalFilter as string) ?? ""}
        onChange={e => table.setGlobalFilter(e.target.value)}
        className="h-8 w-full rounded-md border border-input bg-transparent pl-9 pr-3 text-sm outline-none placeholder:text-muted-foreground focus:border-ring"
      />
    </div>
  )
}

export { DataTableSearch }

"use client"

import * as React from "react"
import { RiCloseLine } from "@remixicon/react"
import type { VariantProps } from "class-variance-authority"

import { buttonVariants } from "@/components/ui/button"
import { useSidebar } from "@/components/ui/sidebar"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

type ButtonVariant = VariantProps<typeof buttonVariants>["variant"]

export type DataTableSelectionBarAction =
  | { icon: React.ElementType; label: string; onClick?: () => void; variant?: ButtonVariant }
  | "separator"

function DataTableSelectionBar({
  count,
  onClear,
  actions,
  label = "selected",
}: {
  count: number
  onClear: () => void
  actions: DataTableSelectionBarAction[]
  label?: string
}) {
  const { open } = useSidebar()
  const visible = count > 0

  return (
    <div
      className={cn(
        "fixed bottom-6 left-0 right-0 z-50 flex justify-center transition-[padding] duration-200 pointer-events-none",
      )}
      style={{ paddingLeft: open ? "var(--sidebar-width)" : undefined }}
    >
      <div
        className={cn(
          "pointer-events-auto transition-all duration-200",
          visible ? "translate-y-0 opacity-100" : "translate-y-3 opacity-0 pointer-events-none",
        )}
      >
        <div className="flex items-center gap-1 rounded-full border bg-popover px-2 py-2 shadow-xl shadow-black/10 ring-1 ring-border/50">
          <div className="flex items-center gap-2 px-2">
            <span className="text-sm font-medium tabular-nums">
              {count} {label}
            </span>
            <button
              onClick={onClear}
              className="flex size-5 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              aria-label="Clear selection"
            >
              <RiCloseLine className="size-3.5" />
            </button>
          </div>

          <TooltipProvider delay={300}>
            {actions.map((action, i) =>
              action === "separator" ? (
                <div key={i} className="mx-1 h-5 w-px shrink-0 bg-border" />
              ) : (
                <Tooltip key={action.label}>
                  <TooltipTrigger
                    onClick={action.onClick}
                    className={buttonVariants({ variant: action.variant ?? "outline", size: "icon-sm" })}
                  >
                    <action.icon />
                  </TooltipTrigger>
                  <TooltipContent>{action.label}</TooltipContent>
                </Tooltip>
              ),
            )}
          </TooltipProvider>
        </div>
      </div>
    </div>
  )
}

export { DataTableSelectionBar }

"use client"

import * as React from "react"
import { type SortingState } from "@tanstack/react-table"
import { RiArrowDownSLine, RiArrowUpDownLine } from "@remixicon/react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

type SortColumn = { id: string; label: string }

function DataTableSortMenu({
  sorting,
  onSortingChange,
  columns,
}: {
  sorting: SortingState
  onSortingChange: (sorting: SortingState) => void
  columns: SortColumn[]
}) {
  const current = sorting[0]

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={
        <Button
          variant="outline"
          size="sm"
          className={cn("rounded-md", current && "border-primary/40 bg-primary/5")}
        />
      }>
        <RiArrowUpDownLine className="opacity-60" />
        {current
          ? `${columns.find(c => c.id === current.id)?.label ?? current.id} ${current.desc ? "↓" : "↑"}`
          : "Sort by"}
        <RiArrowDownSLine className="opacity-60" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-44">
        <DropdownMenuGroup>
          <DropdownMenuLabel>Sort by</DropdownMenuLabel>
          <DropdownMenuSeparator />
          {columns.map(col => (
            <React.Fragment key={col.id}>
              <DropdownMenuCheckboxItem
                checked={current?.id === col.id && !current?.desc}
                onClick={() => onSortingChange([{ id: col.id, desc: false }])}
              >
                {col.label} ↑
              </DropdownMenuCheckboxItem>
              <DropdownMenuCheckboxItem
                checked={current?.id === col.id && current?.desc}
                onClick={() => onSortingChange([{ id: col.id, desc: true }])}
              >
                {col.label} ↓
              </DropdownMenuCheckboxItem>
            </React.Fragment>
          ))}
          {current && (
            <>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={() => onSortingChange([])}>
                Clear sort
              </DropdownMenuItem>
            </>
          )}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

export { DataTableSortMenu }

